import * as THREE from 'three';
import './style.css';

const $ = s => document.querySelector(s);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9aa990);
scene.fog = new THREE.FogExp2(0x9aa990, 0.0065);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, .1, 420);
camera.position.set(0, 2.2, 14);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.08;
$('#game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdce9d7, 0x4c553e, 1.45));
const sun = new THREE.DirectionalLight(0xffe6bd, 2.1); sun.position.set(-65, 110, 30); sun.castShadow = true;
sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-100; sun.shadow.camera.right=100; sun.shadow.camera.top=100; sun.shadow.camera.bottom=-100; sun.shadow.bias=-.0002; scene.add(sun);
const fill = new THREE.DirectionalLight(0xc3d3ee,.45); fill.position.set(70,35,-60); scene.add(fill);
const mat = (color, roughness=.9) => new THREE.MeshStandardMaterial({color,roughness});
const mats={pine:mat(0x42543a),pineDark:mat(0x304431),bark:mat(0x554333),leaf:mat(0x63734a),leaf2:mat(0x7d8550),rock:mat(0x74776a),water:mat(0x587a76,.38),grass:mat(0x899166),fern:mat(0x536845),flower:mat(0xc1a366),deer:mat(0x9a6c45),deerLight:mat(0xc2a177),boar:mat(0x55453a),fox:mat(0xa65d32),bear:mat(0x473b30),dark:mat(0x2b2c26),white:mat(0xe4ddca),antler:mat(0xb7a783),eye:mat(0x161710,.25)};
function terrainHeight(x,z){return Math.sin(x*.035)*2.1+Math.cos(z*.045)*1.6+Math.sin((x+z)*.022)*2.5+Math.max(0,(-z-18)*.075)+Math.sin(x*.12+z*.14)*.23;}
function biomeAt(x,z){if(z< -33)return 'highland';if(x>32)return 'wetland';if(x< -28)return 'pine';return 'meadow';}
function makeTerrain(){const n=110, geo=new THREE.PlaneGeometry(220,220,n,n);geo.rotateX(-Math.PI/2);const p=geo.attributes.position;const colors=[];const c=new THREE.Color();for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);const b=biomeAt(x,z);if(b==='wetland')c.set(0x5e7151);else if(b==='pine')c.set(0x4e6042);else if(b==='highland')c.set(0x797a64);else c.set(0x829062);const noise=(Math.sin(x*3.1+z*2.7)*.025);c.offsetHSL(0,0,noise);colors.push(c.r,c.g,c.b);}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));mesh.receiveShadow=true;scene.add(mesh);}
makeTerrain();
// Water and wandering banks in the eastern marsh.
const water=new THREE.Mesh(new THREE.PlaneGeometry(48,60),mats.water);water.rotation.x=-Math.PI/2;water.position.set(67,1.15,27);scene.add(water);
function addMesh(geo,material,x,y,z,scale=1){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);if(typeof scale==='number')m.scale.setScalar(scale);else m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m;}
const treeGeo=new THREE.ConeGeometry(1,1,7), trunkGeo=new THREE.CylinderGeometry(.13,.25,1,7), rockGeo=new THREE.DodecahedronGeometry(1,0);
function addTree(x,z,kind='pine',s=1){const y=terrainHeight(x,z);const trunk=addMesh(trunkGeo,mats.bark,x,y+1.25*s,z,[s*.62,2.5*s,s*.62]);trunk.rotation.z=Math.sin(x)*.04;const count=kind==='pine'?3:1;for(let i=0;i<count;i++){const geo=kind==='pine'?treeGeo:new THREE.IcosahedronGeometry(1,1);const crown=addMesh(geo,i%2?mats.leaf2:mats.pine,x,y+(2.2+i*.9)*s,z,[s*(kind==='pine'?1.5:1.75),s*(kind==='pine'?2.4:2),s*(kind==='pine'?1.5:1.7)]);crown.position.x+=Math.sin(x+i)*.3*s;}}
function seeded(i){const v=Math.sin(i*127.1+311.7)*43758.5453;return v-Math.floor(v);}
for(let i=0;i<330;i++){const x=seeded(i+1)*200-100,z=seeded(i+509)*200-100,b=biomeAt(x,z);if(b==='wetland'&&seeded(i+24)<.45)continue;if(b==='meadow'&&seeded(i+47)<.70)continue;if(Math.hypot(x,z)<13)continue;const pine=b==='pine'||b==='highland'&&seeded(i+89)<.55;addTree(x,z,pine?'pine':'broadleaf',.7+seeded(i+713)*1.1);}
