 else if(kind==='fox'){ellipsoid(root,bodyGeo,info.material,[0,.6*s,0],[.72*s,.34*s,.32*s]);ellipsoid(root,bodyGeo,info.light,[-.62*s,.56*s,.03*s],[.48*s,.16*s,.17*s]);ellipsoid(root,headGeo,info.material,[.46*s,.91*s,0],[.28*s,.3*s,.23*s]);ellipsoid(root,new THREE.ConeGeometry(.13*s,.37*s,5),info.material,[.4*s,1.23*s,-.16*s],[1,1,1]).rotation.z=-.2;ellipsoid(root,new THREE.ConeGeometry(.13*s,.37*s,5),info.material,[.4*s,1.23*s,.16*s],[1,1,1]).rotation.z=-.2;for(let x of [-.42,.4])for(let z of [-.18,.18])ellipsoid(root,legGeo,info.material,[x*s,.22*s,z*s],[.7,1,.7]);}
 else if(kind==='boar'){ellipsoid(root,bodyGeo,info.material,[0,.75*s,0],[.85*s,.54*s,.48*s]);ellipsoid(root,headGeo,info.material,[.57*s,.9*s,0],[.4*s,.39*s,.37*s]);ellipsoid(root,headGeo,info.light,[.85*s,.75*s,0],[.3*s,.18*s,.25*s]);for(let a of [-1,1])ellipsoid(root,new THREE.ConeGeometry(.08*s,.34*s,5),info.material,[.38*s,1.25*s,a*.22*s],[1,1,1]).rotation.z=-.7;for(let x of [-.5,.48])for(let z of [-.28,.28])ellipsoid(root,legGeo,info.material,[x*s,.31*s,z*s],[1,1,1]);}
 else{ellipsoid(root,bodyGeo,info.material,[0,1.15*s,0],[.72*s,.83*s,.58*s]);ellipsoid(root,headGeo,info.material,[.38*s,2.05*s,0],[.45*s,.47*s,.39*s]);for(let a of [-1,1]){ellipsoid(root,new THREE.SphereGeometry(.18*s,8,7),info.material,[.32*s,2.42*s,a*.28*s],[1,1,1]);ellipsoid(root,legGeo,info.material,[-.42*s,.52*s,a*.34*s],[1.6,1.8,1.5]);ellipsoid(root,legGeo,info.material,[.38*s,.54*s,a*.34*s],[1.5,1.8,1.4]);}}
