const moveForward=new THREE.Vector3(),moveSide=new THREE.Vector3();function update(dt,time){if(!state.started)return;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);const sprint=(keys.ShiftLeft||keys.ShiftRight)&&state.stamina>2&&forward+side!==0;const speed=sprint?10:5.2;if(sprint)state.stamina=Math.max(0,state.stamina-21*dt);else state.stamina=Math.min(100,state.stamina+11*dt);moveForward.set(-Math.sin(yaw),0,-Math.cos(yaw));moveSide.set(Math.cos(yaw),0,-Math.sin(yaw));camera.position.addScaledVector(moveForward,forward*speed*dt);camera.position.addScaledVector(moveSide,side*speed*dt);camera.position.x=THREE.MathUtils.clamp(camera.position.x,-103,103);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-103,103);camera.position.y=terrainHeight(camera.position.x,camera.position.z)+1.72+(forward||side?Math.sin(time*10)*.035:0);camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);
