 function notice(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),2100);}
 function regionName(x,z){const b=biomeAt(x,z);return b==='pine'?'PINE RIDGE':b==='wetland'?'WILLOW MARSH':b==='highland'?'CLOUDLINE PEAK':'FERN MEADOW';}
 function setWeapon(id){state.weapon=(id+weapons.length)%weapons.length;const w=weapons[state.weapon];$('#weaponName').textContent=w.name;$('#weaponType').textContent=w.type;$('#weaponStats').textContent=`ZEROED · ${w.range}M`;$('#ammo').textContent=w.ammo;$('.weapon-key').textContent=state.weapon+1;}
 function getPlayerXZ(){return {x:camera.position.x,z:camera.position.z};}
-function drawMap(){const canvas=$('#minimap'),ctx=canvas.getContext('2d');const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#283529';ctx.fillRect(0,0,w,h);ctx.fillStyle='#354735';ctx.fillRect(0,0,w*.32,h);ctx.fillStyle='#48523b';ctx.fillRect(w*.32,0,w*.33,h);ctx.fillStyle='#394c3d';ctx.fillRect(w*.65,0,w*.35,h);ctx.fillStyle='#3f5041';ctx.fillRect(0,0,w,h*.2);ctx.fillStyle='#617d78';ctx.beginPath();ctx.ellipse(w*.83,h*.7,w*.18,h*.22,-.3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(204,198,158,.38)';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<40;i++){const z=i/39*h,x=w*.44+Math.sin(i*.14)*w*.07;if(!i)ctx.moveTo(x,z);else ctx.lineTo(x,z);}ctx.stroke();const pos=getPlayerXZ();const toMap=(x,z)=>({x:w/2+x/220*w,y:h/2+z/220*h});animals.forEach(a=>{if(!a.alive)return;const d=Math.hypot(a.root.position.x-pos.x,a.root.position.z-pos.z);if(d<55||state.discovered.has(a.index)){const p=toMap(a.root.position.x,a.root.position.z);ctx.fillStyle=state.discovered.has(a.index)?'#e0ad77':'rgba(224,173,119,.52)';ctx.beginPath();ctx.arc(p.x,p.y,2.5,0,Math.PI*2);ctx.fill();}});const p=toMap(pos.x,pos.z);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-yaw);ctx.fillStyle='#eef1df';ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(5,6);ctx.lineTo(0,3);ctx.lineTo(-5,6);ctx.closePath();ctx.fill();ctx.restore();}
