)drawMapCanvas($('#fullMap'),true);}
 function updateHud(){const p=getPlayerXZ();$('#regionName').textContent=regionName(p.x,p.z);$('#coords').textContent=`N ${Math.abs(Math.round(p.z))}° · W ${Math.abs(Math.round(p.x))}°`;$('#stamina').textContent=Math.round(state.stamina);$('.mini-meter:not(.stamina-meter) i').style.width=state.health+'%';$('.stamina-meter i').style.width=state.stamina+'%';drawMap();}
 function nearestAnimal(max=100){let nearest=null,dist=max;animals.forEach(a=>{if(!a.alive)return;const p=a.root.position,d=Math.hypot(p.x-camera.position.x,p.z-camera.position.z);if(d<dist){dist=d;nearest=a;}});return nearest?{animal:nearest,distance:dist}:null;}
 function currentTarget(){raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const meshes=[];animals.forEach(a=>{if(a.alive)a.root.traverse(o=>{if(o.isMesh)meshes.push(o);});});const hits=raycaster.intersectObjects(meshes,false);return hits.length?{animal:hits[0].object.userData.animal,species:hits[0].object.userData.species,distance:hits[0].distance,point:hits[0].point}:null;}
 function scan(){const result=currentTarget();const near=nearestAnimal(95);let a=result?.animal;if(!a&&near&&near.distance<65)a=near.animal;if(!a){notice('NO WILDLIFE IN SIGHT');return;}const distance=camera.position.distanceTo(a.root.position);$('#targetSpecies').textContent=a.info.name;$('#targetAge').textContent=`${a.age} · ${a.sex}`;$('#targetZone').textContent=a.info.habitat;$('#targetDistance').textContent=`${Math.round(distance)} M`;$('#targetCard').classList.remove('hidden');state.discovered.add(a.index);showToast('SPECIES IDENTIFIED',`${a.info.name} · ${a.info.habitat.toLowerCase()}`);setTimeout(()=>$('#targetCard').classList.add('hidden'),4200);}

